// CoreServer is the server API for Core service.
// All implementations must embed UnimplementedCoreServer
// for forward compatibility.
type CoreServer interface {
	// API management
	// group: api
	CreateApi(context.Context, *CreateApiReq) (*ApiInfo, error)
	// group: api
	UpdateApi(context.Context, *UpdateApiReq) (*Empty, error)
	// group: api
	DeleteApi(context.Context, *IDsReq) (*Empty, error)
	// group: api
	GetApiList(context.Context, *ApiListReq) (*ApiListResp, error)
	// group: api
	RegisterApi(context.Context, *CreateApiReq) (*ApiInfo, error)
	// group: auth
	Login(context.Context, *LoginReq) (*LoginResp, error)
	// group: auth
	Refresh(context.Context, *RefreshReq) (*LoginResp, error)
	// group: auth
	Logout(context.Context, *LogoutReq) (*Empty, error)
	// group: auth
	LogoutAll(context.Context, *Empty) (*Empty, error)
	// group: auth
	CheckToken(context.Context, *CheckTokenReq) (*CheckTokenResp, error)
	// group: auth
	Enforce(context.Context, *EnforceReq) (*EnforceResp, error)
	// group: auth
	BootstrapAdmin(context.Context, *BootstrapAdminReq) (*UserPublic, error)
	// group: auth
	BootstrapOperator(context.Context, *BootstrapOperatorReq) (*UserPublic, error)
	// authorization management service
	// group: authority
	UpdateMenuAuthority(context.Context, *MenuAuthReq) (*Empty, error)
	// group: authority
	GetMenuAuthority(context.Context, *RoleIdReq) (*MenuAuthResp, error)
	// group: authority
	UpdateApiAuthority(context.Context, *ApiAuthReq) (*Empty, error)
	// group: authority
	GetApiAuthority(context.Context, *RoleIdReq) (*ApiAuthResp, error)
	// group: base
	Ping(context.Context, *Empty) (*Empty, error)
	// group: catalog
	RegisterCatalog(context.Context, *RegisterCatalogReq) (*Empty, error)
	// I18n management
	// group: i18n
	CreateI18N(context.Context, *CreateI18NReq) (*I18NInfo, error)
	// group: i18n
	UpdateI18N(context.Context, *UpdateI18NReq) (*Empty, error)
	// group: i18n
	UpdateI18NByKey(context.Context, *UpdateI18NByKeyReq) (*Empty, error)
	// group: i18n
	DeleteI18N(context.Context, *IDsReq) (*Empty, error)
	// group: i18n
	GetI18NList(context.Context, *I18NListReq) (*I18NListResp, error)
	// group: i18n
	GetI18NDict(context.Context, *GetI18NDictReq) (*I18NDictResp, error)
	// group: i18n
	CreateI18NLang(context.Context, *CreateI18NLangReq) (*I18NLangInfo, error)
	// group: i18n
	UpdateI18NLang(context.Context, *UpdateI18NLangReq) (*Empty, error)
	// group: i18n
	DeleteI18NLang(context.Context, *IDsReq) (*Empty, error)
	// group: i18n
	GetI18NLangList(context.Context, *I18NLangListReq) (*I18NLangListResp, error)
	// group: i18n
	ReorderI18NLang(context.Context, *ReorderI18NLangReq) (*Empty, error)
	// group: i18n
	GetEnabledI18NLangs(context.Context, *Empty) (*I18NLangListResp, error)
	// group: log
	GetLoginLogList(context.Context, *LoginLogListReq) (*LoginLogListResp, error)
	// group: log
	CreateAdminActionLog(context.Context, *CreateAdminActionLogReq) (*Empty, error)
	// group: log
	GetAdminActionLogList(context.Context, *AdminActionLogListReq) (*AdminActionLogListResp, error)
	// group: log
	CreateErrorLog(context.Context, *CreateErrorLogReq) (*Empty, error)
	// group: log
	GetErrorLogList(context.Context, *ErrorLogListReq) (*ErrorLogListResp, error)
	// Menu management
	// group: menu
	GetMenuByRole(context.Context, *Empty) (*MenuTreeResp, error)
	// group: menu
	CreateMenu(context.Context, *CreateMenuReq) (*MenuInfo, error)
	// group: menu
	UpdateMenu(context.Context, *UpdateMenuReq) (*Empty, error)
	// group: menu
	DeleteMenu(context.Context, *IDsReq) (*Empty, error)
	// group: menu
	GetMenuList(context.Context, *Empty) (*MenuListResp, error)
	// Operator management
	// group: operator
	GetOperator(context.Context, *Empty) (*OperatorInfo, error)
	// group: operator
	UpdateOperator(context.Context, *UpdateOperatorReq) (*Empty, error)
	// group: operator
	IssuePreviewToken(context.Context, *IssuePreviewTokenReq) (*IssuePreviewTokenResp, error)
	// Role management
	// group: role
	CreateRole(context.Context, *CreateRoleReq) (*RoleInfo, error)
	// group: role
	UpdateRole(context.Context, *UpdateRoleReq) (*Empty, error)
	// group: role
	DeleteRole(context.Context, *IDsReq) (*Empty, error)
	// group: role
	GetRoleList(context.Context, *RoleListReq) (*RoleListResp, error)
	// group: role
	GetRoleById(context.Context, *IDReq) (*RoleInfo, error)
	// User management
	// group: user
	GetUserInfo(context.Context, *Empty) (*UserPublic, error)
	// group: user
	GetUserPerm(context.Context, *Empty) (*PermResp, error)
	// group: user
	ChangeOwnPassword(context.Context, *SelfPasswordReq) (*Empty, error)
	// group: user
	CreateUser(context.Context, *CreateUserReq) (*UserPublic, error)
	// group: user
	UpdateUser(context.Context, *UpdateUserReq) (*Empty, error)
	// group: user
	DeleteUser(context.Context, *IDsReq) (*Empty, error)
	// group: user
	GetUserList(context.Context, *UserListReq) (*UserListResp, error)
	// group: user
	GetUserById(context.Context, *IDReq) (*UserPublic, error)
	// group: user
	UpdateUserPassword(context.Context, *PasswordReq) (*Empty, error)
	// group: user
	BindUserRoles(context.Context, *BindRolesReq) (*Empty, error)
	mustEmbedUnimplementedCoreServer()
}

